SELECT
a.*, b.INBKPEND_ORI_BKNO, b.INBKPEND_ORI_STAN, b.INBKPEND_ORI_TX_DATE, b.INBKPEND_ORI_TBSDY_FISC
FROM FEPTXN a
JOIN INBKPEND b
ON a.FEPTXN_TX_DATE = b.INBKPEND_TX_DATE
AND a.FEPTXN_EJFNO = b.INBKPEND_EJFNO
